import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 94 Future champions","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 94 Future champions","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 93 A noble gift","link":"/life/english/new-concept/book-2/unit-04/lesson-093"},"next":{"text":"第二册：实践与进步 · Lesson 95 A fantasy","link":"/life/english/new-concept/book-2/unit-04/lesson-095"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 93 A noble gift","link":"/life/english/new-concept/book-2/unit-04/lesson-093"},"next":{"text":"第二册：实践与进步 · Lesson 95 A fantasy","link":"/life/english/new-concept/book-2/unit-04/lesson-095"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-094.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-094.md"}'),i={name:"life/english/new-concept/book-2/unit-04/lesson-094.md"};function l(r,e,s,h,c,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-94-future-champions" tabindex="-1">第二册：实践与进步 · Lesson 94 Future champions <a class="header-anchor" href="#第二册-实践与进步-·-lesson-94-future-champions" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 94 Future champions&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>学习游泳需要逐步熟悉环境，早期表现不等于未来一定夺冠；练习习惯和能力边界。本课的语言观察是：learn to float 表获得一种能力，practise floating 表练习已经开始做的动作。描述训练规律用一般现在时，不把练习次数直接当作成绩保证。完成学习后，请写一项技能的三阶段学习计划，明确监督条件与进入下一阶段的标准。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>champion</td><td>/ˈtʃæmpiən/</td><td>n.</td><td>冠军</td><td>a future champion</td></tr><tr><td>pool</td><td>/puːl/</td><td>n.</td><td>游泳池</td><td>a heated pool</td></tr><tr><td>train</td><td>/treɪn/</td><td>v.</td><td>训练</td><td>train regularly</td></tr><tr><td>skill</td><td>/skɪl/</td><td>n.</td><td>技能</td><td>develop a skill</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>learn to do — 学会做某事</li><li>under supervision — 在监督照看下，通常不用 a</li></ul><h2 id="语法讲解-一般现在时与习惯" tabindex="-1">语法讲解：一般现在时与习惯 <a class="header-anchor" href="#语法讲解-一般现在时与习惯" aria-label="Permalink to &quot;语法讲解：一般现在时与习惯&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：learn to float 表获得一种能力，practise floating 表练习已经开始做的动作。描述训练规律用一般现在时，不把练习次数直接当作成绩保证。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The children practise floating before they learn to swim across the pool.</p></blockquote><p>孩子们先练习漂浮，再学横穿泳池。</p><p>practise 后接动名词 floating，learn 后接 to swim；before 引出学习顺序，children 为复数。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>practise to float 应改为 practise floating；learn floating 并非此处常用搭配。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>比较 practise floating 与 learn to swim 的结构，注意 children 不加 -s。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The children practise floating before they learn to swim across the pool. A coach stays within reach. Each child moves to the next task only when ready.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一项技能的三阶段学习计划，明确监督条件与进入下一阶段的标准。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：practise 后接动名词 floating，learn 后接 to swim；before 引出学习顺序，children 为复数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：practise to float 应改为 practise floating；learn floating 并非此处常用搭配。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 float：The children practise ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> floating</p><p><strong>解析：</strong> practise 通常接动名词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>孩子们何时进入下一任务？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Only when they are ready.</p><p><strong>解析：</strong> 示范强调准备程度，不是统一时间强制推进。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 learn 写“她正在学游泳”。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She is learning to swim.</p><p><strong>解析：</strong> learn 后接 to 不定式，is learning 表当前学习过程。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般现在时与习惯。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-093">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-095">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(i,[["render",l]]);export{u as __pageData,f as default};
